const menu=[
{name:'Al Taza Special',category:'Rolls',price:230,image:'special.jpg',tag:'THE SIGNATURE',description:'Lebanese-style chicken, fries and cheesy mayo wrapped in soft Rumali roti.'},
{name:'Full Meat Shawarma',category:'Rolls',price:200,image:'full-meat.jpg',tag:'FOR CHICKEN LOVERS',description:'A generous chicken filling with golden fries, mayo and pickled vegetables.'},
{name:'Plate Shawarma Max',category:'Plates',price:325,image:'plate.jpg',tag:'A BIGGER APPETITE',description:'Chicken, crisp salad and fries, served with Rumali roti and creamy mayo.'},
{name:'Paneer Roll',category:'Veg',price:200,image:'paneer.png',tag:'VEGETARIAN FAVOURITE',description:'Spiced paneer, vegetables and crispy fries, wrapped with creamy mayo.'}
];
const regions={Kerala:['Edappally','Kaloor','Aluva','Kakkanad','Angamaly','Kalamassery','Thoppumpady','Thrissur','Palakkad','Calicut','Kannur','Alappuzha','Kollam','Trivandrum','Kottayam','Pallimukku','Thodupuzha','Manjeri'],Bengaluru:['Koramangala','AECS Layout'],Hyderabad:['Kondapur','Asif Nagar'],Sharjah:['Sharjah']};
const $=s=>document.querySelector(s), $$=s=>document.querySelectorAll(s);
function renderMenu(category='All'){
$('#menu-cards').innerHTML=menu.filter(item=>category==='All'||item.category===category).map((item,i)=>`<article class="card" style="--i:${i}"><div class="card-visual"><img src="assets/${item.image}" alt="${item.name}" loading="lazy"><span class="card-number">0${i+1}</span><span class="card-tag">${item.tag}</span><button class="card-preview" data-product="${menu.indexOf(item)}" aria-label="Preview ${item.name}">+</button></div><div class="card-body"><h3>${item.name}</h3><p>${item.description}</p><div class="price"><span>₹${item.price}</span><a href="#outlets">Find an outlet ↗</a></div></div></article>`).join('');
$$('[data-product]').forEach(button=>button.addEventListener('click',()=>openProduct(Number(button.dataset.product))));
}
$$('[data-category]').forEach(button=>button.addEventListener('click',()=>{$$('[data-category]').forEach(other=>{other.classList.toggle('active',other===button);other.setAttribute('aria-pressed',String(other===button));});renderMenu(button.dataset.category);}));
const dialog=$('#product-dialog');
function openProduct(index){const item=menu[index];$('#product-content').innerHTML=`<div class="product-layout"><img src="assets/${item.image}" alt="${item.name}"><div class="product-copy"><p class="eyebrow">${item.tag}</p><h2 id="product-title">${item.name}</h2><p>${item.description}</p><p class="product-price">₹${item.price}</p><p class="small">Prices and availability may vary by outlet.</p><a class="button product-order" href="#outlets">Find an outlet <span>↗</span></a></div></div>`;dialog.showModal();document.body.classList.add('dialog-open');$('.product-order').addEventListener('click',()=>dialog.close());}
$('.dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>document.body.classList.remove('dialog-open'));dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();}});
let selectedOutlet='Edappally';
function renderOutlet(name){selectedOutlet=name;$$('.outlet-list button').forEach(button=>{button.classList.toggle('active',button.textContent===name);button.setAttribute('aria-pressed',String(button.textContent===name));});const edappally=name==='Edappally';$('#outlet-detail').innerHTML=`<p class="eyebrow">AL TAZA / ${$('#region').value.toUpperCase()}</p><h3>${name}</h3><p>${edappally?'Opposite LuLu Shopping Mall, inside Indian Oil Petrol Pump, Metro Pillar P397, NH47, Edappally, Kerala 682024.':'Find this Al Taza on Google Maps for its address, current hours, and contact details.'}</p><p>Dine-in plans? Takeaway cravings?<br>Make your next stop Al Taza.</p><div class="actions"><a class="button" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent('Al Taza '+name+' '+$('#region').value)}" target="_blank" rel="noopener">Get directions <span>↗</span></a><a class="textlink" href="https://al-taza.com/outlets/" target="_blank" rel="noopener">Official outlets ↗</a></div>`;}
function renderRegion(reset=false){if(reset)$('#outlet-search').value='';const names=regions[$('#region').value].filter(name=>name.toLowerCase().includes($('#outlet-search').value.trim().toLowerCase()));$('#outlet-list').innerHTML=names.length?names.map(name=>`<button aria-pressed="false">${name}</button>`).join(''):'<p class="empty-state">No matching outlet. Try another neighbourhood.</p>';$$('.outlet-list button').forEach(button=>button.addEventListener('click',()=>renderOutlet(button.textContent)));if(names.length)renderOutlet(names.includes(selectedOutlet)?selectedOutlet:names[0]);else $('#outlet-detail').innerHTML='<p class="eyebrow">FIND YOUR AL TAZA</p><h3>Try a nearby city.</h3><p>Clear your search or choose another region to see outlets.</p>';}
$('#region').addEventListener('change',()=>renderRegion(true));$('#outlet-search').addEventListener('input',()=>renderRegion());renderMenu();renderRegion();
$$('[data-hero]').forEach(button=>button.addEventListener('click',()=>{const item=menu[Number(button.dataset.hero)];$('#hero-image').src='assets/'+item.image;$('#hero-image').alt=item.name;$$('[data-hero]').forEach(other=>{other.classList.toggle('active',other===button);other.setAttribute('aria-pressed',String(other===button));});}));
const reduced=window.matchMedia('(prefers-reduced-motion: reduce)');
if(!reduced.matches&&'IntersectionObserver' in window){document.documentElement.classList.add('js-motion');const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target);}}),{threshold:.08});$$('.reveal').forEach(element=>observer.observe(element));}
let scrollQueued=false;function updateScroll(){const max=document.documentElement.scrollHeight-window.innerHeight;$('.progress').style.width=(max>0?window.scrollY/max*100:0)+'%';$('header').classList.toggle('scrolled',window.scrollY>35);scrollQueued=false;}
window.addEventListener('scroll',()=>{if(!scrollQueued){scrollQueued=true;requestAnimationFrame(updateScroll);}},{passive:true});updateScroll();
$('.motion-toggle').addEventListener('click',event=>{const paused=document.documentElement.classList.toggle('motion-paused');event.currentTarget.textContent=paused?'▶':'Ⅱ';event.currentTarget.setAttribute('aria-label',paused?'Resume animations':'Pause animations');event.currentTarget.setAttribute('aria-pressed',String(paused));});

$$('[data-city]').forEach(link=>link.addEventListener('click',()=>{$('#region').value='Kerala';$('#outlet-search').value=link.dataset.city;renderRegion();}));

// Reflect the section being viewed in the main navigation.
if('IntersectionObserver' in window){const navObserver=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){const target='#'+entry.target.id;$$('header nav a').forEach(link=>{const active=link.getAttribute('href')===target;link.classList.toggle('active',active);if(active)link.setAttribute('aria-current','location');else link.removeAttribute('aria-current');});}});},{rootMargin:'-15% 0px -60% 0px',threshold:0});$$('#menu,#story,#outlets').forEach(section=>navObserver.observe(section));}
$$('header nav a').forEach(link=>link.addEventListener('click',()=>{$$('header nav a').forEach(other=>{other.classList.toggle('active',other===link);if(other===link)other.setAttribute('aria-current','location');else other.removeAttribute('aria-current');});}));
